"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["49826"],{71175(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.remove_vantagem_sem_vantagem_viva","status":422,"titulo":"A exig\xeancia declara REMOVE_VANTAGEM, mas o processo n\xe3o tem nenhuma vantagem viva para remover"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.remove_vantagem_sem_vantagem_viva","requisitos":["UNI-REQ-0070"],"oQueAconteceu":["A consequ\xeancia `REMOVE_VANTAGEM` tira do candidato uma vantagem que ele teria. Um documento\\nexigido declara essa consequ\xeancia, mas o processo n\xe3o tem vantagem para ser removida: a\\nconfer\xeancia reconhece como vantagem apenas o b\xf4nus regional, e o processo n\xe3o o aplica.","A confer\xeancia acontece quando a configura\xe7\xe3o vai ser congelada, na publica\xe7\xe3o ou na retifica\xe7\xe3o em ato \xfanico. Os documentos exigidos s\xe3o conferidos\\nprimeiro e, depois deles, os grupos de alternativas (OU) com consequ\xeancia pr\xf3pria (ver\\n[`no_exigencia.remove_vantagem_sem_vantagem_viva`](/erros/uniplus.selecao.no_exigencia.remove_vantagem_sem_vantagem_viva)).\\nA primeira viola\xe7\xe3o encontrada interrompe a confer\xeancia."],"comoResolver":["Configure o b\xf4nus regional do processo, se a inten\xe7\xe3o \xe9 que o documento remova essa vantagem,\\nou troque a consequ\xeancia do documento por outra das previstas. Depois, repita a opera\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);